# The mutations of the Python and shell tools of scripts/ (the collection script, the log reader and the blind-test tools; "Leva 2", 11/11/2026) are in their own file:
from mutacoes_scripts import MUTATIONS_SCRIPTS  # noqa: E402

MUTATIONS += MUTATIONS_SCRIPTS


def command_for(classes):
    """The command that runs a mutation's tests: Python test files (`test_*.py`) with unittest, JVM unit test classes with Gradle. A bare name (`test_apk_audit.py`) is found
    in scripts/; one with a folder (`registro/test_chaves.py`, `dev/test_teste_cego.py`) in that folder of scripts/ (the folders are not packages, so discover does not go
    into them by itself); all the files of one mutation have to be in the same folder."""
    if all(c.endswith(".py") for c in classes):
        folders = {str(Path(c).parent) for c in classes}
        if len(folders) != 1:
            raise ValueError(f"the test files of one mutation have to be in one folder: {sorted(classes)}")
        folder = folders.pop()
        base = "scripts" if folder == "." else f"scripts/{folder}"
        return [sys.executable, "-B", "-m", "unittest", "discover", "-s", base, "-t", base, *sum((["-p", Path(c).name] for c in classes), [])]
    return [sys.executable, str(HERE / "run_unit.py"), *classes]


def fatia(items, index, total):
    """The [index]-th (1-based) of [total] slices of [items]: every other one from the index-th, so each slice mixes the files."""
    return [m for n, m in enumerate(items) if n % total == index - 1]


def parse(argv):
    """(slice or None, only list, filters) from the command line."""
    part, only_list, filters, args = None, False, [], list(argv)
    while args:
        a = args.pop(0)
        if a == "--lista":
            only_list = True
        elif a == "--fatia":
            index, total = (int(x) for x in args.pop(0).split("/"))
            if not 1 <= index <= total:
                raise SystemExit(f"--fatia {index}/{total}: the index goes from 1 to {total}")
            part = (index, total)
        else:
            filters.append(a)
    return part, only_list, filters


def main(argv):
    part, only_list, filters = parse(argv)
    back = mutate.recover()
    if back:
        print(f"{back} arquivo(s) deixado(s) mutado(s) por uma execução interrompida foram restaurados", flush=True)
    wanted = [m for m in MUTATIONS if not filters or any(a in m[0] for a in filters)]
    if part:
        wanted = fatia(wanted, *part)
    if only_list:
        print(f"{len(wanted)} mutações")
        for m in wanted:
            print(" ", m[0])
        return 0
    caught = 0
    for name, rel, old, new, classes in wanted:
        caught += mutate.run([(name, rel, old, new)], command_for(classes)) or 0
    print(f"\nTOTAL: {caught} de {len(wanted)} mutações pegas", flush=True)
    return 0 if caught == len(wanted) else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
